//! S14 acceptance: pool quarantine + warm-redial meter signals.
//!
//! Test contract for the S14 build slice (slice S14 of the NNTune v2 roadmap).
//! It pins the meter signals the play path emits for quarantine entry/exit
//! and transparent warm redial, including lanes, backoffs, and noise exclusions.
//!
//! ## Contract the builder implements (do NOT edit this file to match code;
//! change the code to match this file)
//!
//! In `meter.rs`:
//! - `MeterKind::{QuarantineEntered, QuarantineExited, WarmRedial}` — three
//!   distinct events. Entry/exit/redial must be distinguishable from each
//!   other and from the existing `ProviderError`.
//! - `MeterEvent` gains `pub lane: Option<Lane>` (`crate::pool::Lane`) and
//!   `pub backoff_ms: u64`. Unrelated events carry `lane: None` and
//!   `backoff_ms: 0`; existing constructors keep working by setting those
//!   defaults.
//!
//! Emission points in the play path (`play.rs`, pool state in `pool.rs`):
//! - Quarantine entry: a provider-level failure quarantines the pool and
//!   emits one `QuarantineEntered` with the failed call's lane and the
//!   backoff from the `backoff_ms()` ladder: 1s, 5s, 30s, then 5min capped.
//! - Quarantine exit: the first successful call that clears a pending
//!   quarantine emits exactly one `QuarantineExited` (`lane` = clearing
//!   call's lane, `backoff_ms` = 0) and nothing else new — no second entry,
//!   no extra `ProviderError`, normal `BytesServed` intact.
//! - Warm redial: a pooled connection the provider silently closed is
//!   redialed transparently (existing retry-once behavior) and emits exactly
//!   one `WarmRedial` (`lane` = the play's lane, `backoff_ms` = 0). A redial
//!   is not an outage: no quarantine, no `ProviderError`, no entry/exit.
//! - A quarantined pool rejects without dialing and emits no new quarantine
//!   event for the rejection. A gone article (`430`/`423`) fails only its
//!   play and emits no quarantine/redial signal at all.

use std::collections::HashMap;
use std::io::{BufRead, BufReader, Write};
use std::net::{SocketAddr, TcpListener, TcpStream};
use std::sync::{
    atomic::{AtomicBool, AtomicUsize, Ordering},
    Arc,
};
use std::thread;
use std::time::Duration;

use nntune_stream::cache::ContentCache;
use nntune_stream::grant;
use nntune_stream::meter::{MemoryMeter, MeterEvent, MeterKind};
use nntune_stream::play::{play, PlayError, PlayInput, PlayStream, StreamPool};
use nntune_stream::pool::{Lane, Pool};
use nntune_stream::yenc::{self, PartSpec};

const SECRET: &[u8] = b"stream-quarantine-acceptance-secret";
const NOW_UNIX: u64 = 1_700_000_000;
const EXP_UNIX: u64 = NOW_UNIX + 900;
const CIPHER_KEY: u8 = 0x5A;

type Fixture = (Vec<u8>, Vec<String>, HashMap<String, Vec<u8>>);

/// Deterministic pseudo-audio covering every byte value (exercises yEnc
/// escapes), posted the way Usenet does it: one yEnc *multipart* article per
/// `seg_len` bytes.
fn fixture_track(tag: &str, len: usize, seg_len: usize) -> Fixture {
    let mut plain = Vec::with_capacity(len);
    for i in 0..len {
        plain.push(((i * 7919 + tag.len()) % 256) as u8);
    }
    let ciphered: Vec<u8> = plain.iter().map(|b| b ^ CIPHER_KEY).collect();
    let file_crc = yenc::crc32(&ciphered);
    let total = ciphered.len().div_ceil(seg_len) as u32;
    let mut articles = HashMap::new();
    let mut segments = Vec::new();
    for (i, chunk) in ciphered.chunks(seg_len).enumerate() {
        let part = i as u32 + 1;
        let mid = format!("{tag}-seg{i}@synthetic.test");
        let text = yenc::encode_part(
            chunk,
            &format!("{tag}.flac"),
            PartSpec {
                file_size: len as u64,
                part,
                total,
                offset: (i * seg_len) as u64,
                file_crc: (part == total).then_some(file_crc),
            },
        );
        articles.insert(mid.clone(), text);
        segments.push(mid);
    }
    (plain, segments, articles)
}

fn merge(mut a: HashMap<String, Vec<u8>>, b: HashMap<String, Vec<u8>>) -> HashMap<String, Vec<u8>> {
    a.extend(b);
    a
}

/// Minimal NNTP server: greeting + `BODY <mid>` with dot-stuffing.
struct FakeNntp {
    addr: SocketAddr,
    stop: Arc<AtomicBool>,
    connects: Arc<AtomicUsize>,
    bodies: Arc<AtomicUsize>,
    handle: Option<thread::JoinHandle<()>>,
}

impl FakeNntp {
    fn start(articles: HashMap<String, Vec<u8>>) -> Self {
        Self::start_closing_after(articles, usize::MAX)
    }

    /// Like `start`, but the server hangs up after `close_after` BODY
    /// commands on a connection (a provider reaping idle/busy sessions).
    fn start_closing_after(articles: HashMap<String, Vec<u8>>, close_after: usize) -> Self {
        let listener = TcpListener::bind("127.0.0.1:0").expect("bind fake NNTP");
        let addr = listener.local_addr().expect("local addr");
        listener.set_nonblocking(true).expect("nonblocking");
        let stop = Arc::new(AtomicBool::new(false));
        let connects = Arc::new(AtomicUsize::new(0));
        let bodies = Arc::new(AtomicUsize::new(0));
        let (stop_c, connects_c, bodies_c) = (
            Arc::clone(&stop),
            Arc::clone(&connects),
            Arc::clone(&bodies),
        );
        let handle = thread::spawn(move || {
            while !stop_c.load(Ordering::SeqCst) {
                let (stream, _) = match listener.accept() {
                    Ok(pair) => pair,
                    Err(e) if e.kind() == std::io::ErrorKind::WouldBlock => {
                        thread::sleep(Duration::from_millis(5));
                        continue;
                    }
                    Err(_) => break,
                };
                connects_c.fetch_add(1, Ordering::SeqCst);
                Self::serve(stream, &articles, close_after, &bodies_c);
            }
        });
        Self {
            addr,
            stop,
            connects,
            bodies,
            handle: Some(handle),
        }
    }

    fn serve(
        stream: TcpStream,
        articles: &HashMap<String, Vec<u8>>,
        close_after: usize,
        bodies: &AtomicUsize,
    ) {
        let _ = stream.set_read_timeout(Some(Duration::from_secs(2)));
        let mut reader = BufReader::new(stream.try_clone().expect("clone conn"));
        let mut writer = stream;
        let _ = writer.write_all(b"200 synthetic NNTP ready\r\n");
        let mut line = Vec::new();
        let mut served = 0usize;
        loop {
            if served >= close_after {
                break;
            }
            line.clear();
            match reader.read_until(b'\n', &mut line) {
                Ok(0) => break,
                Ok(_) => {}
                Err(_) => break,
            }
            while line.last() == Some(&b'\n') || line.last() == Some(&b'\r') {
                line.pop();
            }
            let cmd = String::from_utf8_lossy(&line).into_owned();
            if let Some(mid) = cmd
                .strip_prefix("BODY ")
                .map(|s| s.trim().trim_matches(|c| c == '<' || c == '>'))
            {
                served += 1;
                bodies.fetch_add(1, Ordering::SeqCst);
                let full_mid = format!("<{mid}>");
                match articles.get(mid) {
                    Some(article) => {
                        let _ =
                            writer.write_all(format!("222 0 {full_mid} follows\r\n").as_bytes());
                        for raw_line in article.split(|&b| b == b'\n') {
                            // Normalize to CRLF; strip a pre-existing CR first.
                            let text_line = raw_line.strip_suffix(b"\r").unwrap_or(raw_line);
                            // Dot-stuff per RFC 3977 §3.1.
                            if text_line.first() == Some(&b'.') {
                                let _ = writer.write_all(b".");
                            }
                            let _ = writer.write_all(text_line);
                            let _ = writer.write_all(b"\r\n");
                        }
                        let _ = writer.write_all(b".\r\n");
                    }
                    None => {
                        let _ = writer.write_all(b"430 no such article\r\n");
                    }
                }
            } else if cmd == "QUIT" {
                let _ = writer.write_all(b"205 bye\r\n");
                break;
            } else {
                let _ = writer.write_all(b"500 unknown command\r\n");
            }
        }
    }

    fn connects(&self) -> usize {
        self.connects.load(Ordering::SeqCst)
    }

    /// BODY commands received so far.
    fn bodies(&self) -> usize {
        self.bodies.load(Ordering::SeqCst)
    }
}

impl Drop for FakeNntp {
    fn drop(&mut self) {
        self.stop.store(true, Ordering::SeqCst);
        // Wake the accept loop promptly.
        let _ = TcpStream::connect(self.addr);
        if let Some(handle) = self.handle.take() {
            let _ = handle.join();
        }
    }
}

fn drain_to_vec(mut stream: PlayStream) -> (Vec<u8>, PlayStream) {
    let mut body = Vec::new();
    for chunk in stream.by_ref() {
        body.extend_from_slice(&chunk);
    }
    (body, stream)
}

#[allow(clippy::too_many_arguments)]
fn input<'a>(
    token: &'a str,
    track_id: &'a str,
    range: Option<&'a str>,
    server: &FakeNntp,
    segments: &'a [String],
    up_next: Option<&'a str>,
) -> PlayInput<'a> {
    PlayInput {
        trace_id: None,
        token,
        track_id,
        range,
        server_addr: server.addr,
        segments,
        segment_ranges: None,
        cipher_key: CIPHER_KEY,
        now_unix: NOW_UNIX,
        up_next,
    }
}

fn grant_for(track: &str) -> String {
    grant::issue("user-1", track, EXP_UNIX, SECRET)
}

fn events_of(meter: &MemoryMeter, kind: MeterKind) -> Vec<&MeterEvent> {
    meter.events.iter().filter(|e| e.kind == kind).collect()
}

#[test]
fn quarantine_entry_emits_lane_and_open_interval() {
    let (_, segments, _) = fixture_track("a", 20_000, 10_000);
    // Live server only to prove a quarantined pool never dials out.
    let server = FakeNntp::start(HashMap::new());
    let mut pool: StreamPool = Pool::new(4);
    let mut cache = ContentCache::new();
    let mut meter = MemoryMeter::default();
    let dead: SocketAddr = "127.0.0.1:1".parse().unwrap();

    // Three consecutive failures open the breaker; later failed half-open
    // probes reopen it for the fixed 30-second interval.
    for n in 0usize..5 {
        if n >= 3 {
            pool.advance(nntune_stream::pool::CIRCUIT_OPEN_MS);
        }
        let token = grant_for("track-a");
        let mut inp = input(&token, "track-a", None, &server, &segments, None);
        inp.server_addr = dead;
        assert!(
            matches!(
                play(&mut pool, &mut cache, &mut meter, SECRET, &inp),
                Err(PlayError::Upstream(_))
            ),
            "outage {n} must fail as an upstream provider error"
        );
        assert_eq!(pool.quarantined(), n >= 2, "outage {n} breaker state");
        let entered = events_of(&meter, MeterKind::QuarantineEntered);
        let expected_entries = n.saturating_sub(1);
        assert_eq!(entered.len(), expected_entries, "breaker entry count");
        if let Some(event) = entered.last() {
            assert_eq!(event.lane, Some(Lane::Playback));
            assert_eq!(event.backoff_ms, nntune_stream::pool::CIRCUIT_OPEN_MS);
            assert_eq!(event.user_id, "user-1");
            assert_eq!(event.track_id, "track-a");
        }
    }
    assert_eq!(events_of(&meter, MeterKind::ProviderError).len(), 5);

    // Still quarantined: the next play is rejected without dialing out and
    // without emitting another quarantine entry.
    let token = grant_for("track-a");
    let inp = input(&token, "track-a", None, &server, &segments, None);
    assert!(matches!(
        play(&mut pool, &mut cache, &mut meter, SECRET, &inp),
        Err(PlayError::PoolQuarantined { .. })
    ));
    assert_eq!(server.connects(), 0, "quarantined pool must not dial out");
    assert_eq!(
        events_of(&meter, MeterKind::QuarantineEntered).len(),
        3,
        "a quarantined rejection emits no new entry event"
    );
    assert_eq!(
        events_of(&meter, MeterKind::ProviderError).len(),
        5,
        "a quarantined rejection is not a new provider error"
    );
}

#[test]
fn successful_call_clearing_quarantine_emits_single_exit_without_noise() {
    let (plain, segments, articles) = fixture_track("a", 40_000, 20_000);
    let server = FakeNntp::start(articles);
    let mut pool: StreamPool = Pool::new(4);
    let mut cache = ContentCache::new();
    let mut meter = MemoryMeter::default();

    // Three failures against a dead port open the breaker.
    let dead: SocketAddr = "127.0.0.1:1".parse().unwrap();
    let token = grant_for("track-a");
    let mut inp = input(&token, "track-a", None, &server, &segments, None);
    inp.server_addr = dead;
    for _ in 0..nntune_stream::pool::CIRCUIT_FAILURE_THRESHOLD {
        assert!(matches!(
            play(&mut pool, &mut cache, &mut meter, SECRET, &inp),
            Err(PlayError::Upstream(_))
        ));
    }
    assert!(pool.quarantined());
    assert_eq!(events_of(&meter, MeterKind::QuarantineEntered).len(), 1);

    // The open interval elapses; the pool recovers on the next successful call.
    pool.advance(nntune_stream::pool::CIRCUIT_OPEN_MS);
    let token2 = grant_for("track-a");
    let inp2 = input(&token2, "track-a", None, &server, &segments, None);
    let resp = play(&mut pool, &mut cache, &mut meter, SECRET, &inp2).expect("recovered play");
    let (body, stream) = drain_to_vec(resp.stream);
    assert_eq!(body, plain);
    stream
        .finalize(&mut pool, &mut cache, &mut meter)
        .expect("finalize");
    assert!(!pool.quarantined(), "success clears the quarantine");

    let exited = events_of(&meter, MeterKind::QuarantineExited);
    assert_eq!(
        exited.len(),
        1,
        "exactly one exit event clears the quarantine"
    );
    assert_eq!(exited[0].lane, Some(Lane::Playback));
    assert_eq!(exited[0].backoff_ms, 0, "exit carries no backoff");
    assert_eq!(exited[0].user_id, "user-1");
    assert_eq!(exited[0].track_id, "track-a");

    assert_eq!(
        events_of(&meter, MeterKind::QuarantineEntered).len(),
        1,
        "recovery emits no second entry"
    );
    assert_eq!(
        events_of(&meter, MeterKind::ProviderError).len(),
        nntune_stream::pool::CIRCUIT_FAILURE_THRESHOLD as usize,
        "recovery emits no extra provider error"
    );
    assert!(
        events_of(&meter, MeterKind::WarmRedial).is_empty(),
        "recovery is not a redial"
    );
    let served: u64 = meter
        .events
        .iter()
        .filter(|e| e.kind == MeterKind::BytesServed && e.track_id == "track-a")
        .map(|e| e.bytes)
        .sum();
    assert_eq!(
        served as usize,
        plain.len(),
        "normal metering for the recovered play is intact"
    );
}

#[test]
fn warm_redial_after_provider_closed_connection_emits_redial_event() {
    let (plain_a, segs_a, arts_a) = fixture_track("a", 20_000, 10_000);
    let (plain_b, segs_b, arts_b) = fixture_track("b", 20_000, 10_000);
    // The server hangs up after 2 BODYs: exactly one track per connection, so
    // the second play finds a stale warm connection and must redial once.
    let server = FakeNntp::start_closing_after(merge(arts_a, arts_b), 2);
    let mut pool: StreamPool = Pool::new(4);
    let mut cache = ContentCache::new();
    let mut meter = MemoryMeter::default();

    for (track, segs, plain) in [
        ("track-a", &segs_a, &plain_a),
        ("track-b", &segs_b, &plain_b),
    ] {
        let token = grant_for(track);
        let inp = input(&token, track, None, &server, segs, None);
        let resp = play(&mut pool, &mut cache, &mut meter, SECRET, &inp).expect("play");
        let (body, stream) = drain_to_vec(resp.stream);
        assert_eq!(&body, plain, "{track}: redial must stay transparent");
        stream
            .finalize(&mut pool, &mut cache, &mut meter)
            .expect("finalize");
    }
    assert_eq!(server.connects(), 2, "stale warm connection was redialed");
    assert_eq!(server.bodies(), 4, "exactly one redial, no fetch storm");
    assert!(
        !pool.quarantined(),
        "a stale pooled connection is not an outage"
    );

    let redialed = events_of(&meter, MeterKind::WarmRedial);
    assert_eq!(redialed.len(), 1, "exactly one redial event");
    assert_eq!(redialed[0].lane, Some(Lane::Playback));
    assert_eq!(redialed[0].backoff_ms, 0, "redial carries no backoff");
    assert_eq!(redialed[0].user_id, "user-1");
    assert_eq!(
        redialed[0].track_id, "track-b",
        "redial belongs to the play that hit the stale connection"
    );

    assert!(
        events_of(&meter, MeterKind::QuarantineEntered).is_empty(),
        "a redial never quarantines"
    );
    assert!(
        events_of(&meter, MeterKind::QuarantineExited).is_empty(),
        "nothing to exit after a redial"
    );
    assert!(
        events_of(&meter, MeterKind::ProviderError).is_empty(),
        "a redial is not a provider error"
    );
}

#[test]
fn missing_article_never_emits_quarantine_or_redial_signals() {
    let (_, segs_gone, _) = fixture_track("gone", 20_000, 10_000);
    let (plain_ok, segs_ok, arts_ok) = fixture_track("ok", 20_000, 10_000);
    // "gone" articles are absent from the server: 430.
    let server = FakeNntp::start(arts_ok);
    let mut pool: StreamPool = Pool::new(4);
    let mut cache = ContentCache::new();
    let mut meter = MemoryMeter::default();

    for _ in 0..2 {
        let token = grant_for("track-gone");
        let inp = input(&token, "track-gone", None, &server, &segs_gone, None);
        assert!(matches!(
            play(&mut pool, &mut cache, &mut meter, SECRET, &inp),
            Err(PlayError::ArticleMissing(_))
        ));
        assert!(!pool.quarantined(), "430 says nothing about the provider");
    }
    for kind in [
        MeterKind::QuarantineEntered,
        MeterKind::QuarantineExited,
        MeterKind::WarmRedial,
        MeterKind::ProviderError,
    ] {
        assert!(
            events_of(&meter, kind).is_empty(),
            "a gone article must not emit {kind:?}"
        );
    }
    assert_eq!(pool.in_use(), 0);

    let token = grant_for("track-ok");
    let inp = input(&token, "track-ok", None, &server, &segs_ok, None);
    let resp = play(&mut pool, &mut cache, &mut meter, SECRET, &inp).expect("healthy track");
    let (body, stream) = drain_to_vec(resp.stream);
    assert_eq!(body, plain_ok);
    stream
        .finalize(&mut pool, &mut cache, &mut meter)
        .expect("finalize");
}
